from fastapi import FastAPI, Header
from fastapi.testclient import TestClient
from pydantic import BaseModel

app = FastAPI()

class MyHeaders(BaseModel):
    my_header: str = Header(default="default", convert_underscores=False)

@app.get("/")
async def read_headers(headers: MyHeaders = Header()):
    return {"my_header": headers.my_header}

client = TestClient(app)

def test_underscore_header_accepted_when_convert_underscores_false():
    response = client.get("/", headers={"my_header": "underscore_value"})
    print(f"Response: {response.json()}")
    assert response.json() == {"my_header": "underscore_value"}

def test_hyphen_header_rejected_when_convert_underscores_false():
    response = client.get("/", headers={"my-header": "hyphen_value"})
    print(f"Response: {response.json()}")
    assert response.json() == {"my_header": "default"}

if __name__ == "__main__":
    try:
        test_underscore_header_accepted_when_convert_underscores_false()
        print("test_underscore_header_accepted_when_convert_underscores_false passed")
    except Exception as e:
        print(f"test_underscore_header_accepted_when_convert_underscores_false failed: {e}")

    try:
        test_hyphen_header_rejected_when_convert_underscores_false()
        print("test_hyphen_header_rejected_when_convert_underscores_false passed")
    except Exception as e:
        print(f"test_hyphen_header_rejected_when_convert_underscores_false failed: {e}")

